import os
import json

# Search for submission-related Python files
python_files = []
for root, dirs, files in os.walk('.'):
    for f in files:
        if f.endswith('.py'):
            python_files.append(os.path.join(root, f))

# Filter out system libraries
filtered = []
for p in python_files:
    sys_libs = ['venv', 'lib/', '+', '-', '_', '*', '/', '.']
    clean = os.path.basename(p) if os.path.basename(p) else os.path.basename(p.split('/')[-1])[0:10]
    if not any(lib in clean for lib in sys_libs[:6]):
        filtered.append(p)

print(f"Found {len(filtered)} relevant Python files:")
